mapper.select:
SELECT  FROM t_photo_file
WHERE status = #{status} AND upload_url_expire_time < #{expireTime}
ORDER BY upload_url_expire_time ASC LIMIT 100

SELECT  FROM t_photo_file
WHERE user_id = #{userId} AND status = 'AVAILABLE' AND file_type = 'ORIGINAL'
AND uploaded_time >= #{startTime}
AND uploaded_time < #{endTime}

    AND (uploaded_time < #{cursorTime} OR (uploaded_time = #{cursorTime} AND id < #{cursorId}))

ORDER BY uploaded_time DESC, id DESC LIMIT #{limit}

SELECT  FROM t_photo_file
WHERE user_id = #{userId} AND status = #{status}
ORDER BY uploaded_time ASC, id ASC
